-- S10 map-owner probe: galactic story script of the probe campaign set "S10 PROBE @@LABEL@@" (human = @@DEFENDER@@ or
-- Underworld; the script is the same for both; generated by
-- tools/probe_mod/s10_map_owners/build_mod.py from s10_story.lua). It starts the land battle by itself:
--   when the story event S10_Begin fires (3 s after the galaxy starts): defenders spawned on @@TARGET@@ for @@DEFENDER@@ (so a battle happens even if the
--   campaign's Starting_Forces did not spawn), Underworld ground units spawned on @@SOURCE@@, assembled into a fleet,
--   moved to @@TARGET@@ (adjacent) and ordered to Invade - the shipped Story_Campaign_Underworld.lua sequence.
-- Trigger: the plot's story event S10_Begin (STORY_ELAPSED 3 s, SCREEN_TEXT reward TEXT_S10_STORY_RUNNING = visible
-- proof that the plot loaded) maps to the Lua state S10_Begin through StoryModeEvents (PGStoryMode).
-- Proof of life of the Lua: _MessagePopup lines (recorded and dismissed by s10reader) and Game_Message.
require("PGStoryMode")

S10_TARGET = "@@TARGET@@"
S10_SOURCE = "@@SOURCE@@"
S10_DEFENDER = "@@DEFENDER@@"
S10_ATTACK_UNITS = { "Underworld_Merc_Squad", "Underworld_Merc_Squad", "Underworld_Disruptor_Merc_Squad",
	"MZ8_Pulse_Cannon_Tank_Company" }
S10_DEFENSE_UNITS = { @@DEFENSE@@ }

function Definitions()
	StoryModeEvents = { S10_Begin = S10_State_Begin }
	S10_Started = false
end

function S10_Say(s)
	pcall(_MessagePopup, "S10 story " .. S10_TARGET .. ": " .. s)
	pcall(Game_Message, "TEXT_S10_STORY_LUA")
end

function S10_State_Begin(message)
	if message == OnEnter and not S10_Started then
		S10_Started = true
		Create_Thread("S10_Invade")
	end
end

function S10_Count(t)
	local n = 0
	if type(t) == "table" then
		for _, _ in pairs(t) do
			n = n + 1
		end
	end
	return n
end

function S10_Invade()
	S10_Say("story script running")
	local uw = Find_Player("Underworld")
	local def = Find_Player(S10_DEFENDER)
	local src = FindPlanet(S10_SOURCE)
	local tgt = FindPlanet(S10_TARGET)
	if not TestValid(src) or not TestValid(tgt) or uw == nil or def == nil then
		S10_Say("setup failed (planet or player missing)")
		return
	end
	local defenders = SpawnList(S10_DEFENSE_UNITS, tgt, def, true, false)
	local units = SpawnList(S10_ATTACK_UNITS, src, uw, false, false)
	S10_Say("spawned " .. S10_Count(defenders) .. " defenders, " .. S10_Count(units) .. " attackers; moving")
	local fleet = Assemble_Fleet(units)
	if not TestValid(fleet) then
		S10_Say("Assemble_Fleet failed")
		return
	end
	BlockOnCommand(fleet.Move_To(tgt))
	Sleep(1)
	local ok, err = pcall(function() fleet.Invade() end)
	S10_Say("Invade issued ok=" .. tostring(ok) .. " " .. tostring(err))
end
